   match('الفعل وما وقع', [('لمح', 'بطرف العين مصادفة'), ('رمق', 'باختلاس أو مراقبة'), ('تأمّل', 'أطال النظر مفكّرًا'), ('حدّق', 'ثبّت النظر بحدّة')]),
   match('الفعل وعموده', [('ذكر', 'يروي: أورد في كلامه'), ('أكّد', 'يحكم: يوهم الثقة'), ('أقرّ', 'يروي: قبِل حين سُئل'), ('اعترف', 'يحكم: صوت المحكمة')]),
   match('المتكلّم وفعله الصحيح', [('رئيس المجلس يقرأ من الورقة مرّة', 'ذكر'), ('الموظّف يجيب عن سؤال', 'أقرّ'), ('رئيس المجلس باسم المجلس', 'صرّح'), ('الموظّف: الباقي ليس عند التنظيم', 'لمّح')]),
   order('رتّب سلّم النظر', ['لمح،', 'رأى،', 'نظر،', 'رمق،', 'تأمّل،', 'حدّق،', 'تفحّص،', 'عاين.']),
   order('رتّب جملة أقرّ', ['أقرّ', 'الموظّف', 'حين', 'سُئل', 'بأنّ', 'الرصيف', 'اكتمل', 'منذ', 'سنة.']),
   order('رتّب الحكم المعلن', ['وبدا', 'لي', 'أنّ', 'رئيس', 'المجلس', 'غير', 'واثق.']),
   pic('من الدرس: «مقهى الجدّ حسن»', ['cafe', 'bank', 'pharmacy'], 0),
