   cloze('أكمل السلّم', '___ بطرف العين مصادفة، و___ أطال النظر مفكّرًا، و___ ثبّت النظر بحدّة.', ['لمح', 'تأمّل', 'حدّق'], ['عاين', 'رمق', 'شاهد']),
   cloze('أكمل العمودين', 'قال وذكر وأقرّ ___، وأكّد واعترف ونفى ___ فلا تُكتب إلّا ___.', ['تروي', 'تحكم', 'بوقوعها'], ['تصف', 'تسأل', 'بالرأي']),
   cloze('أكمل شرط لمّح', 'لمّح قال من غير ___، وشرطها إيراد ___ بعدها ليحكم ___.', ['تصريح', 'الجملة', 'القارئ'], ['صوت', 'الرقم', 'الكاتب']),
   cloze('أكمل الدرس', 'القارئ يظنّ ___ واقعة و___ رأيًا، فمن أراد أن يحكم حكم في جملة ___.', ['الفعل', 'الصفة', 'معلنة'], ['الاسم', 'الحرف', 'قصيرة']),
   tf('قال الجدّ إنّ ريم شاهدت الجلسة.', 'حسن: أنتِ رأيتِ الجلسة ولم تشاهديها، لأنّك تأخّرتِ خمس دقائق.', 'false', 'رأت ولم تشاهد.'),
   tf('صحّح عمر فعلًا قاله الجدّ نفسه.', 'عمر: أنت قلت إنّ ريم اعترفت أنّها تأخّرت. حسن: أقرّت، لا اعترفت. أحسنت يا عمر.', 'true', 'الجدّ يقبل التصحيح.'),
